// Lista los eventos de hoy del calendario principal de Federico.
// Si el nodo Google Calendar fallo (sin credencial o error de API),
// devuelve un mensaje claro en vez de romper.
let events = [];
let calOk = false;
try {
  const cal = $('Google Calendar');
  if (cal.isExecuted) {
    calOk = true;
    events = cal.all().map((item) => item.json);
  }
} catch (e) {
  calOk = false;
}

if (!calOk) {
  return { text: 'No pude leer Google Calendar. Revisá que la credencial Google OAuth2 esté cargada en n8n (Settings > Credentials) y que el workflow esté activo.' };
}

const flat = events[0]?.items ?? events;
if (!flat.length) {
  return { text: 'No tenés eventos para hoy.' };
}

const lines = flat.map((ev) => {
  const start = ev.start?.dateTime || ev.start?.date || '';
  const h = start ? new Date(start) : null;
  const hora = h ? h.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit', hour12: false }) : '';
  const meet = ev.hangoutLink ? `  Meet: ${ev.hangoutLink}` : '';
  return `${hora ? hora + ' - ' : ''}${ev.summary || '(sin titulo)'}${meet}`;
});

return { text: `Eventos de hoy (${flat.length}):\n\n` + lines.join('\n') };
